'use client';

import { useEffect, useState } from 'react';
import { X } from 'lucide-react';
import { apiClient, type ApiContract } from '@/lib/api-client';

export function ContractViewer({ projectId, apiId, versionId, onClose, inline = false }: { projectId: string; apiId: string; versionId: string; onClose: () => void; inline?: boolean }) {
  const [contract, setContract] = useState<ApiContract | null>(null); const [error, setError] = useState('');
  useEffect(() => { void apiClient.registry.contract(projectId, apiId, versionId).then((result) => result.success && result.data ? setContract(result.data) : setError(result.error?.message || 'Could not load this contract.')); }, [projectId, apiId, versionId]);
  if (error) return <div className={inline ? 'contract-inline' : 'contract-drawer'}><button className="graph-close" onClick={onClose} aria-label="Close contract viewer"><X size={16}/></button><div className="data-alert">{error}</div></div>;
  if (!contract) return <div className={inline ? 'contract-inline' : 'contract-drawer'}><div className="data-state">Loading contract…</div></div>;
  const raw = contract.snapshot.normalizedContract as { securityDefinitions?: unknown; components?: { securitySchemes?: unknown }; security?: unknown };
  return <div className={inline ? 'contract-inline' : 'contract-drawer'}>{!inline && <button className="graph-close" onClick={onClose} aria-label="Close contract viewer"><X size={16}/></button>}<p className="page-kicker">Version contract</p><h2>{contract.api.name} · v{contract.version.version}</h2><p className="contract-subtitle">{contract.snapshot.specificationFormat} · source {contract.snapshot.sourceSpecificationVersion || 'not recorded'}</p><div className="contract-overview"><span><b>{contract.endpoints.length}</b> endpoints</span><span><b>{contract.snapshot.checksum.slice(0, 12)}…</b> checksum</span><span><b>{new Date(contract.version.publishedAt || contract.version.createdAt).toLocaleDateString()}</b> released</span></div><section><h3>Endpoints</h3>{contract.endpoints.length ? <div className="contract-endpoints">{contract.endpoints.map((endpoint) => <details key={endpoint.id}><summary><strong>{endpoint.method}</strong> <code>{endpoint.path}</code><span>{endpoint.operationId || endpoint.summary || 'Operation'}</span></summary><div className="contract-endpoint-detail"><p>{endpoint.summary || 'No endpoint description recorded.'}</p><ContractJson label="Parameters" value={endpoint.parameters}/><ContractJson label="Request schema" value={endpoint.requestSchema}/><ContractJson label="Responses" value={endpoint.responseSchema}/><ContractJson label="Security" value={endpoint.security}/><ContractJson label="Expected status codes" value={endpoint.expectedStatusCodes}/></div></details>)}</div> : <p>No endpoints recorded for this version.</p>}</section><section><h3>Security</h3><ContractJson label="Security schemes" value={raw.components?.securitySchemes || raw.securityDefinitions || raw.security}/></section><section><h3>Original specification</h3>{contract.snapshot.originalDocument ? <details><summary>View raw source</summary><pre>{contract.snapshot.originalDocument}</pre></details> : <p>No original source document was stored for this version.</p>}</section></div>;
}

function ContractJson({ label, value }: { label: string; value: unknown }) { if (value === undefined || value === null) return null; return <details className="contract-json"><summary>{label}</summary><pre>{JSON.stringify(value, null, 2)}</pre></details>; }
