'use client';

import Link from 'next/link';
import { FormEvent, useEffect, useState } from 'react';
import { ArrowLeft, Box, GitBranch, Plus, Users } from 'lucide-react';
import { apiClient, type ApiRecord, type ApiVersion, type Project } from '@/lib/api-client';

export function ProjectDashboard({ projectId }: { projectId: string }) {
  const [project, setProject] = useState<Project | null>(null); const [collaborators, setCollaborators] = useState(0); const [apis, setApis] = useState<ApiRecord[]>([]); const [versions, setVersions] = useState<Record<string, ApiVersion[]>>({}); const [name, setName] = useState(''); const [description, setDescription] = useState(''); const [error, setError] = useState(''); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false);
  async function load() { const [projectResult, apiResult] = await Promise.all([apiClient.projects.get(projectId), apiClient.registry.list(projectId)]); if (!projectResult.success || !projectResult.data) { setError(projectResult.error?.message || 'Could not load this project.'); setLoading(false); return; } setProject(projectResult.data.project); setCollaborators(projectResult.data.collaborators.length); if (apiResult.success && apiResult.data) { setApis(apiResult.data); const entries = await Promise.all(apiResult.data.map(async (api) => [api.id, (await apiClient.registry.versions(projectId, api.id)).data || []] as const)); setVersions(Object.fromEntries(entries)); } else setError(apiResult.error?.message || 'Could not load the API registry.'); setLoading(false); }
  useEffect(() => { void load(); }, [projectId]);
  async function createApi(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!name.trim()) return; setBusy(true); setError(''); const result = await apiClient.registry.create(projectId, { name: name.trim(), description: description.trim() || undefined }); setBusy(false); if (!result.success) { setError(result.error?.message || 'Could not register the API.'); return; } setName(''); setDescription(''); await load(); }
  if (loading) return <div className="data-state" role="status">Loading project registry…</div>;
  if (!project) return <div className="data-alert" role="alert">{error || 'Project not found.'}</div>;
  const versionCount = Object.values(versions).reduce((total, list) => total + list.length, 0);
  return <div className="workspace-page"><Link href="/dashboard" className="back-link"><ArrowLeft size={14}/> Organizations and projects</Link><div className="project-hero"><div><p className="page-kicker">Project registry</p><h2>{project.name}</h2><p>{project.description || 'No project description yet.'}</p></div><div className="project-facts"><span><Box size={15}/><b>{apis.length}</b> APIs</span><span><GitBranch size={15}/><b>{versionCount}</b> versions</span><span><Users size={15}/><b>{collaborators}</b> collaborators</span></div></div>{error && <div className="data-alert" role="alert">{error}</div>}<section className="workspace-section"><div className="section-title-row"><div><p className="page-kicker">API registry</p><h3>Registered APIs</h3></div><span>{apis.length} total</span></div>{apis.length ? <div className="registry-list">{apis.map((api) => <article key={api.id}><span className={`lifecycle-dot ${api.lifecycle}`}/><div><b>{api.name}</b><p>{api.description || 'No description.'}</p></div><span className="registry-status">{api.lifecycle}</span><span className="registry-version">{versions[api.id]?.length || 0} versions</span><time>{new Date(api.updatedAt).toLocaleDateString()}</time></article>)}</div> : <div className="empty-state"><GitBranch size={22}/><b>No APIs registered</b><p>Register the first API for this project. No specification is required yet.</p></div>}<form className="project-create" onSubmit={createApi} noValidate><div><label htmlFor="api-name">API name</label><input id="api-name" value={name} onChange={(event) => setName(event.target.value)} placeholder="Orders API" required/></div><div><label htmlFor="api-description">Description</label><input id="api-description" value={description} onChange={(event) => setDescription(event.target.value)} placeholder="Order lifecycle and fulfillment"/></div><button disabled={busy || !name.trim()}><Plus size={15}/> Register API</button></form></section></div>;
}
