'use client';

import { FormEvent, useState } from 'react';
import { Plus, Save, Trash2 } from 'lucide-react';
import { apiClient } from '@/lib/api-client';

type DraftEndpoint = { method: string; path: string; operationId: string; summary: string };
export function ManualApiRegistration({ projectId }: { projectId: string }) {
  const [name, setName] = useState(''); const [description, setDescription] = useState(''); const [version, setVersion] = useState('1.0.0'); const [baseUrl, setBaseUrl] = useState(''); const [protocol, setProtocol] = useState('https'); const [endpoints, setEndpoints] = useState<DraftEndpoint[]>([]); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false);
  function addEndpoint() { setEndpoints((current) => [...current, { method: 'GET', path: '/', operationId: '', summary: '' }]); }
  function updateEndpoint(index: number, field: keyof DraftEndpoint, value: string) { setEndpoints((current) => current.map((endpoint, item) => item === index ? { ...endpoint, [field]: value } : endpoint)); }
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); setError(''); setMessage(''); const api = await apiClient.registry.create(projectId, { name, description }); if (!api.success || !api.data) { setError(api.error?.message || 'Could not create API.'); setBusy(false); return; } const createdVersion = await apiClient.registry.createVersion(projectId, api.data.id, { version, specificationFormat: 'manual' }); if (!createdVersion.success || !createdVersion.data) { setError(createdVersion.error?.message || 'API created, but version creation failed.'); setBusy(false); return; } for (const endpoint of endpoints) { const result = await apiClient.registry.createEndpoint(projectId, api.data.id, createdVersion.data.id, { ...endpoint, summary: endpoint.summary || undefined }); if (!result.success) { setError(result.error?.message || `API created, but endpoint ${endpoint.path} failed.`); setBusy(false); return; } } setBusy(false); setMessage(`${name} ${version} registered successfully.`); setName(''); setDescription(''); setBaseUrl(''); setEndpoints([]); }
  return <div className="workspace-page"><div className="workspace-section"><div className="section-title-row"><div><p className="page-kicker">API management</p><h3>Manual API registration</h3><p>Create an API and immutable version without importing a specification.</p></div><Save size={18}/></div>{error && <div className="data-alert" role="alert">{error}</div>}{message && <div className="data-success" role="status">{message}</div>}<form className="manual-api-form" onSubmit={submit} noValidate><label>API name<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Orders API" required/></label><label>API version<input value={version} onChange={(event) => setVersion(event.target.value)} placeholder="1.0.0" required/></label><label className="manual-wide">Description<textarea value={description} onChange={(event) => setDescription(event.target.value)} placeholder="What this API owns"/></label><label>Base URL<input type="url" value={baseUrl} onChange={(event) => setBaseUrl(event.target.value)} placeholder="https://api.example.com"/></label><label>Protocol<select value={protocol} onChange={(event) => setProtocol(event.target.value)}><option>https</option><option>http</option><option>soap</option></select></label><div className="manual-wide manual-endpoints"><div className="section-title-row"><div><p className="page-kicker">Endpoints</p><h3>Endpoint definitions</h3></div><button type="button" className="button button-quiet" onClick={addEndpoint}><Plus size={14}/> Add endpoint</button></div>{endpoints.map((endpoint, index) => <div className="manual-endpoint" key={index}><select value={endpoint.method} onChange={(event) => updateEndpoint(index, 'method', event.target.value)}><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select><input value={endpoint.path} onChange={(event) => updateEndpoint(index, 'path', event.target.value)} placeholder="/orders" required/><input value={endpoint.operationId} onChange={(event) => updateEndpoint(index, 'operationId', event.target.value)} placeholder="listOrders"/><input value={endpoint.summary} onChange={(event) => updateEndpoint(index, 'summary', event.target.value)} placeholder="List orders"/><button type="button" aria-label="Remove endpoint" onClick={() => setEndpoints((current) => current.filter((_, item) => item !== index))}><Trash2 size={15}/></button></div>)}</div><button className="app-button manual-submit" disabled={busy || !name.trim() || !version.trim()}><Save size={15}/>{busy ? 'Registering…' : 'Register API'}</button></form></div></div>;
}
